//! Name lookups backed by the PCI ID Repository (`https://pci-ids.ucw.cz/`).
//!
//! The tables are generated by `build.rs` from `vendor/pci-ids/pci.ids`. All vendor, class,
//! subclass and programming interface names are always included, but device names are only
//! included for a set of key vendors unless the `pci_ids_full` feature is enabled. To update the
//! database run `just update-pci-ids`.

use core::fmt::{self, Display, Formatter};

/// A reference to a name in [`NAME_POOL`] keyed by the packed numeric ID it belongs to.
struct PciIdName {
    key: u32,
    start: u32,
    len: u16,
}

impl PciIdName {
    const fn new(key: u32, start: u32, len: u16) -> Self {
        Self {
            key,
            start,
            len,
        }
    }

    fn name(&self) -> &'static str {
        let start = self.start as usize;
        &NAME_POOL[start..start + self.len as usize]
    }
}

mod generated {
    use super::PciIdName;

    include!(concat!(env!("OUT_DIR"), "/pci_ids.rs"));
}

use generated::{CLASSES, DEVICES, NAME_POOL, PROG_IFS, SUBCLASSES, VENDORS};

fn lookup(table: &'static [PciIdName], key: u32) -> Option<&'static str> {
    table.binary_search_by_key(&key, |entry| entry.key).ok().map(|i| table[i].name())
}

pub fn vendor_name(vendor_id: u16) -> Option<&'static str> {
    lookup(&VENDORS, vendor_id as u32)
}

pub fn device_name(vendor_id: u16, device_id: u16) -> Option<&'static str> {
    lookup(&DEVICES, ((vendor_id as u32) << 16) | device_id as u32)
}

pub fn class_name(class_code: u8) -> Option<&'static str> {
    lookup(&CLASSES, class_code as u32)
}

pub fn subclass_name(class_code: u8, subclass: u8) -> Option<&'static str> {
    lookup(&SUBCLASSES, ((class_code as u32) << 8) | subclass as u32)
}

pub fn prog_if_name(class_code: u8, subclass: u8, prog_if: u8) -> Option<&'static str> {
    lookup(&PROG_IFS, ((class_code as u32) << 16) | ((subclass as u32) << 8) | prog_if as u32)
}

/// Human readable description of a full PCI class code, formatted as
/// `Class: Subclass (Programming Interface)` with each part omitted if it is not in the database.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PciClassDescription {
    pub class_code: u8,
    pub subclass: u8,
    pub prog_if: u8,
}

impl Display for PciClassDescription {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        let Some(class) = class_name(self.class_code) else {
            return write!(f, "Unknown Class");
        };
        write!(f, "{class}")?;
        if let Some(subclass) = subclass_name(self.class_code, self.subclass) {
            write!(f, ": {subclass}")?;
            if let Some(prog_if) = prog_if_name(self.class_code, self.subclass, self.prog_if) {
                write!(f, " ({prog_if})")?;
            }
        }
        Ok(())
    }
}
